import {
  allStarterKeys,
  type ModelSlotsState,
  type ModelSlotsView,
  offeringKey,
  parseOfferingKey,
  type Slot,
  type SlotModelView,
  starterSlot,
} from "@shared/modelSlots";
import { catalogEntry } from "@shared/providers";
import type { ModelsCatalogView } from "@shared/quota";
import { QUOTA_TO_PI_PROVIDER } from "@shared/quota";
import type { SettingsStore } from "../storage/settingsStore";
import type { PiModelRef, SlottedRef } from "./routingEngine";

/**
 * User-assigned intelligence slots: which of a subscription's models
 * Firstmate may route work to on its own, and as what.
 *
 * Three behaviors carry the whole design:
 *
 * - SEEDING. An offering this install has never seen is placed from the
 *   starter map (or left off). Seeding never overwrites a seen key.
 * - NEWCOMERS. A later arrival is announced once: in the map → placed;
 *   not in the map → off until the user places it.
 * - THE FALLBACK. If nothing anywhere is slotted, routing does not stop:
 *   it applies the starter map virtually, then the full signed-in pool
 *   at medium. A shortlist is a preference, never a way to brick the app.
 *
 * Off is not a sign-out: an unslotted model is still available, and an
 * explicit pin still reaches it (naming a model is its own placement).
 */

export type NewModelNotice = {
  providerId: string;
  id: string;
  /** Set when the starter map placed it; omitted when it arrived off. */
  slot?: Slot;
};

export type AccountModels = {
  accountId: string;
  accountLabel: string;
  providerId: string;
  models: { provider: string; id: string }[];
};

export type ModelSlotsOptions = {
  settings: SettingsStore;
  accounts: () => AccountModels[];
  quotaModels: () => ModelsCatalogView | undefined;
};

export class ModelSlots {
  /** Offerings announced as newcomers this session, for the Settings "new" mark. */
  private lastNew = new Set<string>();

  constructor(private readonly options: ModelSlotsOptions) {}

  /**
   * Seeds never-seen offerings from the starter map and records newcomers
   * on the ones that have been seen. Returns the newcomers so the caller
   * can announce them exactly once; a first-time seed for a provider
   * announces nothing, because none of those models is new to the user.
   */
  reconcile(): NewModelNotice[] {
    const state = this.read();
    const seen = new Set(state.seen);
    const notices: NewModelNotice[] = [];
    let changed = false;
    const providerHadHistory = new Map<string, boolean>();

    for (const account of this.options.accounts()) {
      if (!providerHadHistory.has(account.providerId)) {
        const prefix = `${account.providerId}/`;
        providerHadHistory.set(
          account.providerId,
          state.seen.some((key) => key.startsWith(prefix)),
        );
      }
      const firstForProvider = providerHadHistory.get(account.providerId) !== true;
      for (const model of account.models) {
        const key = offeringKey(model);
        if (seen.has(key)) continue;
        seen.add(key);
        state.seen.push(key);
        changed = true;
        const seed = starterSlot(model.provider, model.id);
        if (seed) state.assignments[key] = seed;
        if (!firstForProvider) {
          notices.push({
            providerId: account.providerId,
            id: model.id,
            ...(seed ? { slot: seed } : {}),
          });
        }
      }
    }
    if (changed) this.write(state);
    this.lastNew = new Set(notices.map((notice) => `${notice.providerId}/${notice.id}`));
    return notices;
  }

  /**
   * The routable pool for one grain: `available` narrowed to what has a
   * slot, with the fallback ladder applied and its rung named. Each model
   * carries the slot routing will walk.
   */
  routable(available: PiModelRef[]): { models: SlottedRef[]; note: string } {
    const assigned = this.slottedOf(available);
    if (assigned.length > 0) {
      return {
        models: assigned,
        note: `${assigned.length} of ${available.length} available models have a slot`,
      };
    }
    const approved = new Set(allStarterKeys());
    const defaults = available.flatMap((model) => {
      const key = offeringKey(model);
      if (!approved.has(key)) return [];
      const slot = starterSlot(model.provider, model.id);
      return slot ? [{ ...model, slot }] : [];
    });
    if (defaults.length > 0) {
      const state = this.read();
      const hadAssignments = Object.keys(state.assignments).length > 0;
      return {
        models: defaults,
        note: hadAssignments
          ? `no slotted model is available; using the starter map (${defaults.length})`
          : `no models slotted; using the starter map (${defaults.length})`,
      };
    }
    return {
      models: available.map((model) => ({ ...model, slot: "medium" as const })),
      note: "no slotted or starter-map model is available; using every signed-in model",
    };
  }

  /** The assigned slot for one offering, or undefined when it is off. */
  slotOf(ref: PiModelRef): Slot | undefined {
    return this.read().assignments[offeringKey(ref)];
  }

  /** Places one offering in a slot, or turns it off. Unknown keys are ignored. */
  setSlot(key: string, slot: Slot | null): void {
    const offered = this.offeredKeys();
    if (!offered.has(key)) return;
    const state = this.read();
    if (!state.seen.includes(key)) state.seen.push(key);
    if (slot) state.assignments[key] = slot;
    else delete state.assignments[key];
    this.lastNew.delete(key);
    this.write(state);
  }

  /**
   * Rewrites currently available offerings to the starter map (or off).
   * `seen` and pins are untouched. Scoped to one provider, or all.
   */
  reset(providerId?: string): void {
    const state = this.read();
    for (const key of this.offeredKeys()) {
      const { provider, id } = parseOfferingKey(key);
      if (providerId && provider !== providerId) continue;
      const seed = starterSlot(provider, id);
      if (seed) state.assignments[key] = seed;
      else delete state.assignments[key];
    }
    this.write(state);
  }

  /** The slot-first Settings board: one row per offering, provider on the row. */
  view(): ModelSlotsView {
    const state = this.read();
    const catalog = this.catalogByKey();
    const byKey = new Map<string, SlotModelView>();
    for (const account of this.options.accounts()) {
      for (const model of account.models) {
        const key = offeringKey(model);
        if (byKey.has(key)) continue;
        const row = catalog.get(key);
        byKey.set(key, {
          provider: model.provider,
          providerLabel: catalogEntry(account.providerId)?.name ?? account.providerId,
          id: model.id,
          label: row?.label ?? model.id,
          slot: state.assignments[key] ?? null,
          ...(this.lastNew.has(key) ? { isNew: true as const } : {}),
        });
      }
    }
    const models = [...byKey.values()].sort((a, b) => {
      const provider = a.providerLabel.localeCompare(b.providerLabel);
      if (provider !== 0) return provider;
      return a.id.localeCompare(b.id);
    });
    return { models, usingDefaults: this.assignedInPool().size === 0 };
  }

  private slottedOf(available: PiModelRef[]): SlottedRef[] {
    const state = this.read();
    return available.flatMap((model) => {
      const slot = state.assignments[offeringKey(model)];
      return slot ? [{ ...model, slot }] : [];
    });
  }

  private assignedInPool(): Set<string> {
    const state = this.read();
    const offered = this.offeredKeys();
    const keys = new Set<string>();
    for (const [key, slot] of Object.entries(state.assignments)) {
      if (slot && offered.has(key)) keys.add(key);
    }
    return keys;
  }

  private offeredKeys(): Set<string> {
    const keys = new Set<string>();
    for (const account of this.options.accounts()) {
      for (const model of account.models) keys.add(offeringKey(model));
    }
    return keys;
  }

  private catalogByKey(): Map<string, { label: string }> {
    const byKey = new Map<string, { label: string }>();
    for (const model of this.options.quotaModels()?.models ?? []) {
      const piProvider = QUOTA_TO_PI_PROVIDER[model.provider];
      if (!piProvider) continue;
      byKey.set(`${piProvider}/${model.id}`, { label: model.label });
    }
    return byKey;
  }

  private read(): ModelSlotsState {
    return this.options.settings.getModelSlots();
  }

  private write(state: ModelSlotsState): void {
    this.options.settings.setModelSlots(state);
  }
}

import { allStarterKeys, STARTER_SLOTS } from "@shared/modelSlots";
import type { ModelsCatalogView } from "@shared/quota";
import { describe, expect, it } from "vitest";
import { openInMemoryDatabase } from "../storage/db";
import { SettingsStore } from "../storage/settingsStore";
import { type AccountModels, ModelSlots } from "./modelSlots";

function build(accounts: AccountModels[], catalog?: ModelsCatalogView) {
  const settings = new SettingsStore(openInMemoryDatabase());
  let rows = accounts;
  const slots = new ModelSlots({
    settings,
    accounts: () => rows,
    quotaModels: () => catalog,
  });
  return { slots, settings, setAccounts: (next: AccountModels[]) => (rows = next) };
}

const copilot: AccountModels = {
  accountId: "acct-copilot",
  accountLabel: "work",
  providerId: "github-copilot",
  models: [
    { provider: "github-copilot", id: "claude-opus-5" },
    { provider: "github-copilot", id: "gpt-5.6-sol" },
    { provider: "github-copilot", id: "gemini-3.6-flash" },
    { provider: "github-copilot", id: "claude-fable-5" },
  ],
};

const codex: AccountModels = {
  accountId: "acct-codex",
  accountLabel: "personal",
  providerId: "openai-codex",
  models: [
    { provider: "openai-codex", id: "gpt-5.6-sol" },
    { provider: "openai-codex", id: "claude-opus-5" },
    { provider: "openai-codex", id: "gpt-5.6-terra" },
  ],
};

describe("the starter map", () => {
  it("carries exactly the eighteen settled rows", () => {
    expect(allStarterKeys()).toHaveLength(18);
  });

  it("keys per provider, so the same id can sit in two slots", () => {
    expect(STARTER_SLOTS["github-copilot"]?.["gpt-5.6-sol"]).toBe("high");
    expect(STARTER_SLOTS["openai-codex"]?.["gpt-5.6-sol"]).toBe("high");
    expect(STARTER_SLOTS["openai-codex"]?.["claude-opus-5"]).toBeUndefined();
  });

  it("leaves Copilot claude-fable-5 off (superseded by 5.1)", () => {
    expect(STARTER_SLOTS["github-copilot"]?.["claude-fable-5"]).toBeUndefined();
  });

  it("places Fable 5.1 as a premium starter row, guarded until it ships", () => {
    expect(STARTER_SLOTS["anthropic-claude"]?.["claude-fable-5-1"]).toBe("premium");
    expect(STARTER_SLOTS["github-copilot"]?.["claude-fable-5.1"]).toBe("premium");
  });

  it("places gpt-6-astra as premium on Codex and Copilot", () => {
    expect(STARTER_SLOTS["openai-codex"]?.["gpt-6-astra"]).toBe("premium");
    expect(STARTER_SLOTS["github-copilot"]?.["gpt-6-astra"]).toBe("premium");
  });

  it("places Claude haiku in low", () => {
    expect(STARTER_SLOTS["anthropic-claude"]?.["claude-haiku-4-5"]).toBe("low");
  });
});

describe("ModelSlots.reconcile - first activation only", () => {
  it("seeds a new account from its provider's starter rows, and only those rows", () => {
    const { slots } = build([copilot, codex]);
    expect(slots.reconcile()).toEqual([]);
    expect(slots.slotOf({ provider: "github-copilot", id: "claude-opus-5" })).toBe("high");
    expect(slots.slotOf({ provider: "github-copilot", id: "gpt-5.6-sol" })).toBe("high");
    expect(slots.slotOf({ provider: "openai-codex", id: "gpt-5.6-sol" })).toBe("high");
    expect(slots.slotOf({ provider: "openai-codex", id: "gpt-5.6-terra" })).toBe("medium");
    expect(slots.slotOf({ provider: "openai-codex", id: "claude-opus-5" })).toBeUndefined();
    expect(slots.slotOf({ provider: "github-copilot", id: "gemini-3.6-flash" })).toBeUndefined();
    expect(slots.slotOf({ provider: "github-copilot", id: "claude-fable-5" })).toBeUndefined();
  });

  it("says nothing on a first seed - none of those models is new to the user", () => {
    const { slots } = build([copilot]);
    expect(slots.reconcile()).toEqual([]);
  });

  it("announces a live-catalog newcomer once and leaves an unmapped one off", () => {
    const { slots, setAccounts } = build([copilot]);
    slots.reconcile();
    setAccounts([
      {
        ...copilot,
        models: [...copilot.models, { provider: "github-copilot", id: "gpt-5.7-sol" }],
      },
    ]);
    expect(slots.reconcile()).toEqual([{ providerId: "github-copilot", id: "gpt-5.7-sol" }]);
    expect(slots.slotOf({ provider: "github-copilot", id: "gpt-5.7-sol" })).toBeUndefined();
    expect(slots.reconcile()).toEqual([]);
  });

  it("places a mapped newcomer and names the slot in the notice", () => {
    const { slots, setAccounts } = build([codex]);
    slots.reconcile();
    setAccounts([
      {
        ...codex,
        models: [...codex.models, { provider: "openai-codex", id: "gpt-6-astra" }],
      },
    ]);
    expect(slots.reconcile()).toEqual([
      { providerId: "openai-codex", id: "gpt-6-astra", slot: "premium" },
    ]);
    expect(slots.slotOf({ provider: "openai-codex", id: "gpt-6-astra" })).toBe("premium");
  });

  it("never overwrites a user's existing choice, including off", () => {
    const { slots } = build([copilot]);
    slots.reconcile();
    slots.setSlot("github-copilot/claude-opus-5", "low");
    slots.setSlot("github-copilot/gpt-5.6-sol", null);
    expect(slots.reconcile()).toEqual([]);
    expect(slots.slotOf({ provider: "github-copilot", id: "claude-opus-5" })).toBe("low");
    expect(slots.slotOf({ provider: "github-copilot", id: "gpt-5.6-sol" })).toBeUndefined();
  });
});

describe("ModelSlots.setSlot - assign and reassign", () => {
  it("places an offered model, reassigns it, and turns it off", () => {
    const { slots } = build([copilot]);
    slots.reconcile();
    slots.setSlot("github-copilot/gemini-3.6-flash", "low");
    expect(slots.slotOf({ provider: "github-copilot", id: "gemini-3.6-flash" })).toBe("low");
    slots.setSlot("github-copilot/gemini-3.6-flash", "high");
    expect(slots.slotOf({ provider: "github-copilot", id: "gemini-3.6-flash" })).toBe("high");
    slots.setSlot("github-copilot/gemini-3.6-flash", null);
    expect(slots.slotOf({ provider: "github-copilot", id: "gemini-3.6-flash" })).toBeUndefined();
  });

  it("ignores keys the live pool does not serve", () => {
    const { slots } = build([copilot]);
    slots.reconcile();
    slots.setSlot("github-copilot/not-a-real-model", "high");
    expect(slots.slotOf({ provider: "github-copilot", id: "not-a-real-model" })).toBeUndefined();
  });
});

describe("ModelSlots.reset - both grains", () => {
  it("resets one provider without touching a sibling", () => {
    const { slots } = build([copilot, codex]);
    slots.reconcile();
    slots.setSlot("github-copilot/claude-opus-5", "low");
    slots.setSlot("openai-codex/gpt-5.6-sol", "low");
    slots.reset("github-copilot");
    expect(slots.slotOf({ provider: "github-copilot", id: "claude-opus-5" })).toBe("high");
    expect(slots.slotOf({ provider: "openai-codex", id: "gpt-5.6-sol" })).toBe("low");
  });

  it("resets every provider to the starter map, leaving seen and pins alone", () => {
    const { slots, settings } = build([copilot, codex]);
    slots.reconcile();
    slots.setSlot("github-copilot/claude-opus-5", "low");
    slots.setSlot("openai-codex/gpt-5.6-sol", null);
    slots.setSlot("github-copilot/gemini-3.6-flash", "medium");
    const seenBefore = settings.getModelSlots().seen.slice();
    slots.reset();
    expect(slots.slotOf({ provider: "github-copilot", id: "claude-opus-5" })).toBe("high");
    expect(slots.slotOf({ provider: "openai-codex", id: "gpt-5.6-sol" })).toBe("high");
    expect(slots.slotOf({ provider: "github-copilot", id: "gemini-3.6-flash" })).toBeUndefined();
    expect(slots.slotOf({ provider: "github-copilot", id: "claude-fable-5" })).toBeUndefined();
    expect(settings.getModelSlots().seen).toEqual(seenBefore);
  });
});

describe("ModelSlots.routable - the fallback ladder", () => {
  const available = [
    { provider: "github-copilot", id: "claude-opus-5" },
    { provider: "github-copilot", id: "gemini-3.6-flash" },
  ];

  it("narrows to the slotted subset when there is one", () => {
    const { slots } = build([copilot]);
    slots.reconcile();
    const routable = slots.routable(available);
    expect(routable.models).toEqual([
      { provider: "github-copilot", id: "claude-opus-5", slot: "high" },
    ]);
    expect(routable.note).toBe("1 of 2 available models have a slot");
  });

  it("falls back to the starter map when NOTHING is slotted", () => {
    const { slots } = build([copilot]);
    slots.reconcile();
    slots.setSlot("github-copilot/claude-opus-5", null);
    slots.setSlot("github-copilot/gpt-5.6-sol", null);
    const routable = slots.routable(available);
    expect(routable.models).toEqual([
      { provider: "github-copilot", id: "claude-opus-5", slot: "high" },
    ]);
    expect(routable.note).toMatch(/using the starter map/);
  });

  it("falls back to the whole signed-in pool rather than routing nothing", () => {
    const { slots } = build([copilot]);
    const orphan = [{ provider: "openrouter", id: "some/experimental-model" }];
    const routable = slots.routable(orphan);
    expect(routable.models).toEqual([
      { provider: "openrouter", id: "some/experimental-model", slot: "medium" },
    ]);
    expect(routable.note).toBe(
      "no slotted or starter-map model is available; using every signed-in model",
    );
  });
});

