import { mkdirSync, mkdtempSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { expect, type Page, test } from "@playwright/test";
import {
  closeStubCursorUsage,
  type StubCursorUsage,
  startStubCursorUsage,
} from "./cursorUsageStub";
import { type LaunchedApp, launchApp } from "./launch";
import {
  claudeDefaultStore,
  seedSignedInClaudeStore,
  writeMockClaudeClient,
} from "./mockClaudeClient";
import { seedSignedInCursorStore, writeMockCursorClient } from "./mockCursorClient";

/**
 * The Subscriptions "Models" section, run against the REAL catalog path -
 * no FM3000_QUOTA_FIXTURE_DIR. That fixture substitutes a hand-authored
 * two-model catalog for the whole fetcher, which is exactly why the section
 * could list providers the user had never signed in to without any test
 * noticing: piAuth.catalogModels() and buildModelsCatalog() never ran e2e.
 *
 * Here they do. Claude and Cursor are signed in through their stand-in
 * clients; Grok has an account but it is switched off; Codex, Copilot and
 * Kimi were never connected at all. Only the first two may appear.
 *
 * Nothing in this test reaches the network: the enabled Claude account
 * resolves no usage credential - its stand-in store has no credentials file
 * and no Keychain item exists for a throwaway config root - so the sensor
 * reports auth_required without any HTTP; Grok is disabled; Cursor's usage
 * RPC is pointed at a local stub (`FM3000_CURSOR_USAGE_URL`) so CD-4=B2
 * cannot phone api2.cursor.sh. The model catalog comes from pi-ai's bundled
 * data (launch.ts sets PI_OFFLINE).
 */

const GROK_DISABLED = "acct_grok_off";
const CLAUDE_PERSONAL = "acct_claude1";
const CURSOR_PERSONAL = "acct_cursor1";

function seedAccounts(userDataDir: string): void {
  const accountsDir = join(userDataDir, "accounts");
  const grokDir = join(accountsDir, "xai", GROK_DISABLED);
  mkdirSync(grokDir, { recursive: true, mode: 0o700 });
  writeFileSync(
    join(grokDir, "auth.json"),
    JSON.stringify({ xai: { type: "api_key", key: "x" } }),
    {
      mode: 0o600,
    },
  );
  mkdirSync(join(accountsDir, "anthropic-claude", CLAUDE_PERSONAL), {
    recursive: true,
    mode: 0o700,
  });
  seedSignedInCursorStore(join(accountsDir, "cursor", CURSOR_PERSONAL));
  writeFileSync(
    join(accountsDir, "registry.json"),
    JSON.stringify({
      version: 1,
      accounts: [
        {
          id: GROK_DISABLED,
          providerId: "xai",
          kind: "api_key",
          label: "Personal",
          // Signed in, but switched off: it leaves the selection pool, so it
          // leaves this section too.
          enabled: false,
          createdAt: Date.parse("2026-08-01T00:00:00Z"),
        },
        {
          id: CLAUDE_PERSONAL,
          providerId: "anthropic-claude",
          kind: "subscription_oauth",
          label: "Personal Max",
          enabled: true,
          createdAt: Date.parse("2026-08-02T00:00:00Z"),
        },
        {
          id: CURSOR_PERSONAL,
          providerId: "cursor",
          kind: "subscription_oauth",
          label: "Personal Pro",
          enabled: true,
          createdAt: Date.parse("2026-08-03T00:00:00Z"),
        },
      ],
      pins: {},
    }),
    { mode: 0o600 },
  );
}

let launched: LaunchedApp;
let cursorUsage: StubCursorUsage;

test.beforeAll(async () => {
  const userDataDir = mkdtempSync(join(tmpdir(), "fm3000-e2e-"));
  seedAccounts(userDataDir);
  cursorUsage = await startStubCursorUsage({ accept: ["stub"] });
  launched = await launchApp({
    withMockProvider: true,
    userDataDir,
    prepareHome: (homeDir) => seedSignedInClaudeStore(claudeDefaultStore(homeDir)),
    env: {
      FM3000_CLAUDE_CLI: writeMockClaudeClient(mkdtempSync(join(tmpdir(), "fm3000-claude-stub-"))),
      FM3000_CURSOR_CLI: writeMockCursorClient(mkdtempSync(join(tmpdir(), "fm3000-cursor-stub-"))),
      FM3000_CURSOR_USAGE_URL: cursorUsage.url,
    },
  });
  await launched.page.getByRole("button", { name: "Settings" }).click();
  await launched.page.getByRole("tab", { name: "Subscriptions" }).click();
});

test.afterAll(async () => {
  await launched.close();
  await closeStubCursorUsage(cursorUsage);
});

/** The section is a collapsed disclosure since the Instruments relayout. */
async function openModels(page: Page) {
  const models = page.getByRole("region", { name: "Models" });
  await expect(models).toBeVisible({ timeout: 20_000 });
  const head = models.getByRole("button", { name: /^Models/ });
  if ((await head.getAttribute("aria-expanded")) !== "true") await head.click();
  await expect(head).toHaveAttribute("aria-expanded", "true");
  return models;
}

test("the models section lists the connected subscriptions only", async () => {
  const { page } = launched;
  const models = await openModels(page);

  // The two connected subscriptions, with rows from the real catalog.
  await expect(models.getByText("Claude", { exact: true }).first()).toBeVisible();
  await expect(models.getByText("Cursor", { exact: true }).first()).toBeVisible();
  await expect(models.getByRole("button", { name: "Claude Opus 5", exact: true })).toBeVisible();
  await expect(
    models
      .locator('[data-slot-group="off"]')
      .getByRole("button", { name: "Composer 2.5", exact: true }),
  ).toBeVisible();

  // Providers with no usable account contribute nothing, though the
  // provider-wide catalog behind the section still carries them.
  for (const label of ["Codex", "Copilot", "Grok", "Kimi"]) {
    await expect(models.getByText(label, { exact: true })).toHaveCount(0);
  }
  // A Pi model id that only the un-gated global catalog could have supplied.
  await expect(models.getByText("GPT-5.5", { exact: true })).toHaveCount(0);
  // The list above is unaffected: the paused Grok account still has its
  // row (dimmed, "paused"), and the foot offers another.
  await expect(page.locator(`[data-account-row="${GROK_DISABLED}"]`)).toHaveAttribute(
    "data-paused",
    "true",
  );
  await expect(page.getByRole("button", { name: "Add another Grok account" })).toBeVisible();

  await page.screenshot({ path: "test-results/screens/dark-settings-models-connected.png" });
});

test("a connected provider's models are pinnable from the section", async () => {
  const { page } = launched;
  const models = await openModels(page);
  const row = models.getByRole("button", { name: "Claude Opus 5", exact: true });
  await row.click();
  await expect(models.getByRole("button", { name: "Claude Opus 5 ✱" })).toBeVisible();
  await models.getByRole("button", { name: "Claude Opus 5 ✱" }).click();
  await expect(models.getByRole("button", { name: "Claude Opus 5 ✱" })).toHaveCount(0);
});

import type { AccountView } from "@shared/accounts";
import type { QuotaProviderView } from "@shared/quota";
import { KEYCHAIN_VALUE_FAILURE_DETAIL } from "@shared/quota";
import { describe, expect, it } from "vitest";
import { CLAUDE_FIRST_RUN_TEXT, rowView } from "./SubscriptionsTab";

const account: AccountView = {
  id: "acct_cl1",
  providerId: "anthropic-claude",
  kind: "subscription_oauth",
  label: "Personal",
  enabled: true,
  connected: true,
  pinned: false,
  createdAt: 1,
};

describe("Subscriptions rowView: Keychain VALUE refusal", () => {
  it("shows the sensor's reason as a retryable failure, never a meter and never sign-in", () => {
    const row: QuotaProviderView = {
      provider: "claude",
      label: "Claude",
      accountId: "acct_cl1",
      status: "unavailable",
      reason: "keychain_access_denied",
      detail: KEYCHAIN_VALUE_FAILURE_DETAIL.keychain_access_denied,
      stale: false,
      windows: [],
    };
    const view = rowView(account, row, Date.now());
    expect(view.kind).toBe("unavailable");
    expect(view.stateText).toBe(KEYCHAIN_VALUE_FAILURE_DETAIL.keychain_access_denied);
    expect(view.retry).toBe(true);
    expect(view.signIn).toBe(false);
    expect(view.meters).toEqual([]);
  });

  it("keeps last-known-good meters with a Retry when the refresh was a Keychain refusal", () => {
    const row: QuotaProviderView = {
      provider: "claude",
      label: "Claude",
      accountId: "acct_cl1",
      status: "unavailable",
      reason: "keychain_access_denied",
      detail: KEYCHAIN_VALUE_FAILURE_DETAIL.keychain_access_denied,
      stale: true,
      measuredAt: Date.now() - 3_600_000,
      windows: [{ id: "session", label: "session", percentRemaining: 74, pace: "behind" }],
    };
    const view = rowView(account, row, Date.now());
    expect(view.kind).toBe("stale");
    expect(view.retry).toBe(true);
    expect(view.meters[0]?.percent).toBe(74);
    expect(view.signIn).toBe(false);
    expect(view.stateText).toBe(KEYCHAIN_VALUE_FAILURE_DETAIL.keychain_access_denied);
  });

  it("a terminal auth_required row keeps the Sign in CTA, even with last-known-good windows", () => {
    const row: QuotaProviderView = {
      provider: "claude",
      label: "Claude",
      accountId: "acct_cl1",
      status: "auth_required",
      reason: "rejected_after_renewal",
      stale: true,
      measuredAt: Date.now() - 3_600_000,
      windows: [{ id: "session", label: "session", percentRemaining: 74, pace: "behind" }],
    };
    const view = rowView(account, row, Date.now());
    expect(view.kind).toBe("auth");
    expect(view.signIn).toBe(true);
    expect(view.retry).toBe(false);
    expect(view.stateText).toBe("Sign in again to read usage.");
    expect(view.meters).toEqual([]);
  });

  it("local needsReauth proof is the same CTA, even before a quota row lands", () => {
    const view = rowView({ ...account, needsReauth: true }, undefined, Date.now());
    expect(view.kind).toBe("auth");
    expect(view.signIn).toBe(true);
    expect(view.retry).toBe(false);
    expect(view.stateText).toBe("Sign in again to read usage.");
    expect(view.dot).toBe("danger");
    expect(view.stateTone).toBe("danger");
  });

  it("a no-interactive-session failure is retryable and never a re-auth CTA", () => {
    const row: QuotaProviderView = {
      provider: "claude",
      label: "Claude",
      accountId: "acct_cl1",
      status: "unavailable",
      reason: "keychain_no_interactive_session",
      detail: KEYCHAIN_VALUE_FAILURE_DETAIL.keychain_no_interactive_session,
      stale: false,
      windows: [],
    };
    const view = rowView(account, row, Date.now());
    expect(view.kind).toBe("unavailable");
    expect(view.stateText).toBe(KEYCHAIN_VALUE_FAILURE_DETAIL.keychain_no_interactive_session);
    expect(view.retry).toBe(true);
    expect(view.signIn).toBe(false);
  });

  it("an unreadable store is retryable and never a re-auth CTA", () => {
    const row: QuotaProviderView = {
      provider: "claude",
      label: "Claude",
      accountId: "acct_cl1",
      status: "unavailable",
      reason: "keychain_unreadable",
      detail: KEYCHAIN_VALUE_FAILURE_DETAIL.keychain_unreadable,
      stale: false,
      windows: [],
    };
    const view = rowView(account, row, Date.now());
    expect(view.kind).toBe("unavailable");
    expect(view.retry).toBe(true);
    expect(view.signIn).toBe(false);
  });
});

describe("Subscriptions rowView: Claude first-run", () => {
  const unsigned: AccountView = { ...account, connected: false };

  it("treats a missing Claude login as first-run, not a failed re-auth", () => {
    const view = rowView(unsigned, undefined, Date.now());
    expect(view.kind).toBe("disconnected");
    expect(view.stateText).toBe(CLAUDE_FIRST_RUN_TEXT);
    expect(view.signIn).toBe(true);
    expect(view.stateTone).toBeUndefined();
    expect(view.dot).toBe("ring");
    expect(view.dotLabel).toBe("not signed in yet");
    expect(view.meters).toEqual([]);
  });

  it("keeps a disconnected non-Claude row as sign-in-again", () => {
    const other: AccountView = { ...unsigned, providerId: "openrouter" };
    const view = rowView(other, undefined, Date.now());
    expect(view.stateText).toBe("Sign in again.");
    expect(view.stateTone).toBe("danger");
    expect(view.signIn).toBe(true);
    expect(view.dot).toBe("danger");
  });
});

import type React from "react";
import { useEffect, useRef, useState } from "react";
import { IconButton } from "./IconButton";

export type RowMenuItem =
  | {
      id: string;
      label: string;
      onSelect?: () => void;
      /** The one destructive item; last, behind a separator. */
      tone?: "danger";
      /** A trailing glyph, e.g. the ✱ pin. */
      trailing?: React.ReactNode;
    }
  | { separator: true };

export type RowMenuProps = {
  /** Accessible name of the kebab, e.g. "Work #2 actions". */
  label: string;
  items: RowMenuItem[];
  /** Kebab size; 28 in a 50px list row. */
  size?: number;
  style?: React.CSSProperties;
};

const kebab = (
  <svg width="14" height="14" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true">
    <circle cx="5" cy="12" r="1.6" />
    <circle cx="12" cy="12" r="1.6" />
    <circle cx="19" cy="12" r="1.6" />
  </svg>
);

/**
 * The ⋯ at the end of a list row (design skill RowMenu): every action the
 * row offers, out of the glance path. Anchored bottom-right; closes on
 * Escape, an outside click, or a pick. Arrow keys walk the items and focus
 * returns to the kebab on close, so the menu is a keyboard citizen.
 */
export function RowMenu({ label, items, size = 28, style }: RowMenuProps) {
  const [open, setOpen] = useState(false);
  const wrap = useRef<HTMLSpanElement>(null);
  const menu = useRef<HTMLDivElement>(null);
  const trigger = useRef<HTMLButtonElement>(null);

  useEffect(() => {
    if (!open) return;
    const onDown = (event: PointerEvent) => {
      if (wrap.current && !wrap.current.contains(event.target as Node)) setOpen(false);
    };
    const onKey = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        // The menu owns this Escape: the shell's own listener (which would
        // close Settings) must not also see it.
        event.stopPropagation();
        setOpen(false);
        trigger.current?.focus();
        return;
      }
      if (event.key !== "ArrowDown" && event.key !== "ArrowUp") return;
      const focusable = [
        ...(menu.current?.querySelectorAll<HTMLButtonElement>('[role="menuitem"]') ?? []),
      ];
      if (focusable.length === 0) return;
      event.preventDefault();
      const index = focusable.indexOf(document.activeElement as HTMLButtonElement);
      const step = event.key === "ArrowDown" ? 1 : -1;
      const next = focusable[(index + step + focusable.length) % focusable.length];
      next?.focus();
    };
    document.addEventListener("pointerdown", onDown);
    document.addEventListener("keydown", onKey);
    menu.current?.querySelector<HTMLButtonElement>('[role="menuitem"]')?.focus();
    return () => {
      document.removeEventListener("pointerdown", onDown);
      document.removeEventListener("keydown", onKey);
    };
  }, [open]);

  return (
    <span
      ref={wrap}
      style={{ position: "relative", flexShrink: 0, display: "inline-flex", ...style }}
    >
      <IconButton
        ref={trigger}
        label={label}
        size={size}
        aria-haspopup="menu"
        aria-expanded={open}
        onClick={() => setOpen((value) => !value)}
      >
        {kebab}
      </IconButton>
      {open && (
        <div
          ref={menu}
          role="menu"
          aria-label={label}
          style={{
            position: "absolute",
            right: 0,
            top: size + 4,
            zIndex: 4,
            minWidth: 180,
            background: "var(--bg-2)",
            border: "1px solid var(--line-2)",
            borderRadius: "var(--radius-m)",
            boxShadow: "var(--shadow-2)",
            padding: 6,
            display: "flex",
            flexDirection: "column",
            gap: 2,
          }}
        >
          {items.map((item, index) =>
            "separator" in item ? (
              <hr
                // biome-ignore lint/suspicious/noArrayIndexKey: separators have no identity
                key={`separator-${index}`}
                style={{
                  height: 1,
                  border: 0,
                  background: "var(--line-1)",
                  margin: "4px 2px",
                }}
              />
            ) : (
              <MenuItem
                key={item.id}
                item={item}
                onPick={() => {
                  setOpen(false);
                  trigger.current?.focus();
                  item.onSelect?.();
                }}
              />
            ),
          )}
        </div>
      )}
    </span>
  );
}

function MenuItem({
  item,
  onPick,
}: {
  item: Exclude<RowMenuItem, { separator: true }>;
  onPick: () => void;
}) {
  const [hover, setHover] = useState(false);
  return (
    <button
      type="button"
      role="menuitem"
      onClick={onPick}
      onMouseEnter={() => setHover(true)}
      onMouseLeave={() => setHover(false)}
      style={{
        background: hover ? "var(--bg-3)" : "transparent",
        border: 0,
        textAlign: "left",
        padding: "7px 10px",
        borderRadius: "var(--radius-s)",
        fontFamily: "var(--font-ui)",
        fontSize: "var(--text-sm)",
        color: item.tone === "danger" ? "var(--danger)" : "var(--fg-1)",
        cursor: "pointer",
        display: "flex",
        justifyContent: "space-between",
        alignItems: "center",
        gap: 12,
        whiteSpace: "nowrap",
      }}
    >
      <span>{item.label}</span>
      {item.trailing}
    </button>
  );
}

